create table "public"."comments" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "post_id" bigint,
    "user_id" bigint,
    "body" text,
    "parent_comment_id" bigint
);


alter table "public"."comments" enable row level security;

create table "public"."communities" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "name" text,
    "creator_id" bigint
);


alter table "public"."communities" enable row level security;

create table "public"."moderators" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "user_id" bigint,
    "community_id" bigint
);


alter table "public"."moderators" enable row level security;

create table "public"."posts" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "title" text,
    "body" text,
    "user_id" bigint,
    "category" text,
    "community_id" bigint default '1'::bigint,
    "pinned" boolean
);


alter table "public"."posts" enable row level security;

create table "public"."users" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "username" text,
    "user_id" uuid default gen_random_uuid()
);


alter table "public"."users" enable row level security;

CREATE UNIQUE INDEX comments_pkey ON public.comments USING btree (id);

CREATE UNIQUE INDEX communities_pkey ON public.communities USING btree (id);

CREATE UNIQUE INDEX moderators_pkey ON public.moderators USING btree (id);

CREATE UNIQUE INDEX posts_pkey ON public.posts USING btree (id);

CREATE UNIQUE INDEX usernames_pkey ON public.users USING btree (id);

CREATE UNIQUE INDEX usernames_user_id_key ON public.users USING btree (user_id);

CREATE UNIQUE INDEX usernames_username_key ON public.users USING btree (username);

alter table "public"."comments" add constraint "comments_pkey" PRIMARY KEY using index "comments_pkey";

alter table "public"."communities" add constraint "communities_pkey" PRIMARY KEY using index "communities_pkey";

alter table "public"."moderators" add constraint "moderators_pkey" PRIMARY KEY using index "moderators_pkey";

alter table "public"."posts" add constraint "posts_pkey" PRIMARY KEY using index "posts_pkey";

alter table "public"."users" add constraint "usernames_pkey" PRIMARY KEY using index "usernames_pkey";

alter table "public"."comments" add constraint "comments_post_id_fkey" FOREIGN KEY (post_id) REFERENCES posts(id) not valid;

alter table "public"."comments" validate constraint "comments_post_id_fkey";

alter table "public"."comments" add constraint "comments_user_id_fkey" FOREIGN KEY (user_id) REFERENCES users(id) ON UPDATE RESTRICT ON DELETE RESTRICT not valid;

alter table "public"."comments" validate constraint "comments_user_id_fkey";

alter table "public"."communities" add constraint "communities_creator_id_fkey" FOREIGN KEY (creator_id) REFERENCES users(id) not valid;

alter table "public"."communities" validate constraint "communities_creator_id_fkey";

alter table "public"."moderators" add constraint "moderators_community_id_fkey" FOREIGN KEY (community_id) REFERENCES communities(id) not valid;

alter table "public"."moderators" validate constraint "moderators_community_id_fkey";

alter table "public"."moderators" add constraint "moderators_user_id_fkey" FOREIGN KEY (user_id) REFERENCES users(id) not valid;

alter table "public"."moderators" validate constraint "moderators_user_id_fkey";

alter table "public"."posts" add constraint "posts_community_id_fkey" FOREIGN KEY (community_id) REFERENCES communities(id) not valid;

alter table "public"."posts" validate constraint "posts_community_id_fkey";

alter table "public"."posts" add constraint "posts_user_id_fkey" FOREIGN KEY (user_id) REFERENCES users(id) not valid;

alter table "public"."posts" validate constraint "posts_user_id_fkey";

alter table "public"."users" add constraint "usernames_user_id_key" UNIQUE using index "usernames_user_id_key";

alter table "public"."users" add constraint "usernames_username_key" UNIQUE using index "usernames_username_key";

