create policy "Enable insert for users based on user_id"
on "public"."comments"
as permissive
for insert
to public
with check ((( SELECT auth.uid() AS uid) = ( SELECT users.user_id
   FROM users
  WHERE (users.id = comments.user_id))));


create policy "Enable read access for all users"
on "public"."comments"
as permissive
for select
to public
using (true);


create policy "update comment based on id"
on "public"."comments"
as permissive
for update
to public
using ((( SELECT auth.uid() AS uid) = ( SELECT users.user_id
   FROM users
  WHERE (users.id = comments.user_id))));


create policy "Enable read access for all users"
on "public"."communities"
as permissive
for select
to public
using (true);


create policy "insert"
on "public"."communities"
as permissive
for insert
to public
with check ((( SELECT auth.uid() AS uid) = ( SELECT users.user_id
   FROM users
  WHERE (users.id = communities.creator_id))));


create policy "insert"
on "public"."moderators"
as permissive
for insert
to public
with check ((( SELECT auth.uid() AS uid) = ( SELECT users.user_id
   FROM users
  WHERE (users.id = moderators.user_id))));


create policy "Enable insert for users based on user_id"
on "public"."posts"
as permissive
for insert
to public
with check ((( SELECT auth.uid() AS uid) = ( SELECT users.user_id
   FROM users
  WHERE (users.id = posts.user_id))));


create policy "Enable read access for all users"
on "public"."posts"
as permissive
for select
to public
using (true);


create policy "update posts based on user id"
on "public"."posts"
as permissive
for update
to public
using ((( SELECT auth.uid() AS uid) = ( SELECT users.user_id
   FROM users
  WHERE (users.id = posts.user_id))));


create policy "Enable insert for users based on user_id"
on "public"."users"
as permissive
for insert
to public
with check ((( SELECT auth.uid() AS uid) = user_id));


create policy "Enable read access for all users"
on "public"."users"
as permissive
for select
to public
using (true);



